// Node example: exchange vaulted JWT -> short-lived token -> call embeddings
const axios = require('axios');
async function getToken(jwtAssertion) {
  const r = await axios.post('https://api.redwood.ai/oauth/token', {
    grant_type: 'urn:ietf:params:oauth:grant-type:jwt-bearer',
    assertion: jwtAssertion
  });
  return r.data.access_token;
}
async function embed(text) {
  const token = await getToken(process.env.JWT_ASSERTION);
  const r = await axios.post('https://api.redwood.ai/v1/embeddings', {
    model: 'redwood-embed-1024',
    input: text
  }, { headers: { Authorization: `Bearer ${token}` } });
  return r.data;
}

